/*
 * A221865  The nonprimes k such that k + 2 is either a prime or a semiprime.
 * https://oeis.org/A221865
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth non‑prime integer k (including 0 and 1) such
 *            that * k + 2 is either prime or semiprime (product of two
 *            primes, counting * multiplicity). The sequence is generated by a
 *            simple sieve-like search * over k
 * Range:     u8 n <= 69, u16 n <= 69, u32 n <= 69, u64 n <= 69, u128 n <= 69,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* --- Dependencies ----------------------------------------------------- */
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/is_prime_big.h"          /* is_prime_big(seq_t) */

#define INITIAL_CAP 64

/* --- Static cache (thread‑local) ------------------------------------ */
static seq_t *cache = NULL;          /* cached sequence values          */
static size_t cache_len = 0;         /* number of elements stored       */
static size_t cache_cap = 0;         /* allocated capacity              */
static uint64_t next_k = 0;          /* next candidate k to test        */

/* --- Helper: check whether n is a semiprime (exactly 2 prime factors) --- */
static bool is_semiprime(uint64_t n)
{
    if (n <= 3)
        return false;
    uint64_t count = 0;
    for (uint64_t d = 2; d * d <= n; ++d) {
        while (n % d == 0) {
            ++count;
            n /= d;
            if (count > 2)
                return false;
        }
    }
    if (n > 1)
        ++count;
    return count == 2;
}

/* --- Helper: add value to the cache ----------------------------------- */
static void cache_add(uint64_t k)
{
    if (cache_len == cache_cap) {
        size_t new_cap = (cache_cap == 0) ? INITIAL_CAP : cache_cap << 1;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (!tmp)
            abort(); /* fatal: out of memory */
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = (seq_t)k;
}

/* --- Ensure the cache contains at least n terms ----------------------- */
static void ensure_cache(idx_t n)
{
    if (cache_len >= (size_t)n)
        return;

    while (cache_len < (size_t)n) {
        /* skip primes (is_prime_big returns false for 0,1) */
        if (!is_prime_big((seq_t)next_k)) {
            seq_t target = (seq_t)(next_k + 2);
            if (is_prime_big(target) || is_semiprime((uint64_t)target))
                cache_add(next_k);
        }
        ++next_k;
    }
}

/* --- Public interface ------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;                 /* undefined; harmless for our use */
    ensure_cache(n);
    return cache[n - 1];
}
